 readonly Plugin plugin;readonly List<Entity> transient=new();readonly Autodesk.AutoCAD.Geometry.IntegerCollection viewports=new();readonly PaletteSet palette;readonly Label detail;readonly Button approve;readonly Button cancel;PlanRecord? current;Document? document;string revision="";bool approved;DateTime expires;DateTime lastValidation;NativePreviewScene? scene;
 internal NativeReview(Plugin p){plugin=p;palette=new PaletteSet("AI CAD · Duyệt bản vẽ",new Guid("f62f0837-19ab-4cb5-b102-1ea6f5819011")){MinimumSize=new Size(300,400),Size=new Size(350,600),Style=PaletteSetStyles.ShowCloseButton|PaletteSetStyles.ShowAutoHideButton|PaletteSetStyles.ShowPropertiesMenu};var panel=new Panel{Dock=DockStyle.Fill,BackColor=Color.FromArgb(248,250,252),Padding=new Padding(18)};var heading=new Label{Text="AI CAD  /  PREVIEW",Dock=DockStyle.Top,Height=40,Font=new System.Drawing.Font("Segoe UI",13,FontStyle.Bold),ForeColor=Color.FromArgb(40,93,221)};detail=new Label{Text="Chọn một nhiệm vụ trong app để tạo bản xem trước.",Dock=DockStyle.Fill,Font=new System.Drawing.Font("Segoe UI",10),ForeColor=Color.FromArgb(25,37,58),AutoEllipsis=false};approve=new Button{Text="Duyệt & áp dụng",Dock=DockStyle.Bottom,Height=46,Enabled=false,BackColor=Color.FromArgb(40,93,221),ForeColor=Color.White,FlatStyle=FlatStyle.Flat};cancel=new Button{Text="Hủy bản xem trước",Dock=DockStyle.Bottom,Height=42,Enabled=false};approve.Click+=(_,__)=>{try{Demand();approved=true;approve.Enabled=false;document!.SendStringToExecute("AICADAPPLY\n",true,false,false);}catch(System.Exception e){Invalidate(e.Message);}};cancel.Click+=(_,__)=>Cancel();panel.Controls.Add(detail);panel.Controls.Add(heading);panel.Controls.Add(cancel);panel.Controls.Add(approve);palette.Add("Duyệt kế hoạch",panel);}
 internal void ShowPalette()=>palette.Visible=true;
 internal void Prepare(string id){Cancel();var store=plugin.Plans;using(store.Lock(id)){var r=store.Read(id);if(r.Status!="READY"&&r.Status!="PREVIEW")throw new CadException("INVALID_STATE","Plan already cancelled/dispatched/completed.");if(r.Hash!=JsonUtil.Hash(r.Plan))throw new CadException("PLAN_CHANGED","Plan hash differs.");Validation.Plan(r.Plan);if(r.Plan.SessionId!=plugin.Context.SessionId)throw new CadException("WRONG_SESSION","Plan belongs to another session.");var d=plugin.Context.Resolve(r.Plan.DocumentId,r.Plan.DocumentRevision);if(AcApp.DocumentManager.MdiActiveDocument!=d||!d.Database.TileMode||d.Database.Insunits!=UnitsValue.Millimeters)throw new CadException("WRONG_CONTEXT","Activate target DWG in Model space, units mm.");NativeWriteGuard.Check(d);DemandResources(r.Plan);DemandSources(r.Plan);var task=Reader.Scan(d).SingleOrDefault(t=>t.TaskId==r.Plan.TaskId&&t.Handle==r.Plan.TaskHandle);if(task==null||task.Warnings.Count>0||task.SkillId!=r.Plan.SkillId||task.TemplateId!=r.Plan.Template.Id||JsonUtil.Hash(task.Scope)!=JsonUtil.Hash(r.Plan.TaskScope??r.Plan.Scope)||JsonUtil.Hash(task.OutputPoint??task.Scope[0])!=JsonUtil.Hash(r.Plan.OutputPoint??r.Plan.Scope[0]))throw new CadException("TASK_CHANGED","Task identity/boundary changed.");var preferences=PreviewPreferences.Load(plugin.Config.DataRoot);bool showGraphics=preferences.DrawGraphics(r.Plan);var previousWorking=HostApplicationServices.WorkingDatabase;try{scene=new NativePreviewScene(r.Plan);HostApplicationServices.WorkingDatabase=scene.Database;if(showGraphics)foreach(var e in scene.Entities){e.ColorIndex=3;if(!TransientManager.CurrentTransientManager.AddTransient(e,TransientDrawingMode.DirectShortTerm,128,viewports)){e.Dispose();throw new CadException("PREVIEW_FAILED","Cannot display transient graphics.");}transient.Add(e);}}catch{Cleanup();throw;}finally{HostApplicationServices.WorkingDatabase=previousWorking;}current=r;document=d;revision=plugin.Context.Revision(d);expires=DateTime.UtcNow.AddMinutes(5);r.Status="PREVIEW";r.Message=showGraphics?"Preview displayed in AutoCAD. Waiting for local human approval.":"Geometry validated in staging; visual preview skipped by "+preferences.Mode+". Waiting for local human approval.";store.Write(r);approved=false;approve.Enabled=true;cancel.Enabled=true;palette.Visible=true;detail.Text="CHẾ ĐỘ: "+preferences.Mode+(showGraphics?" / Có nét xem trước":" / Chỉ phiếu xác nhận")+"\n\nDUYỆT TRƯỚC "+expires.ToLocalTime().ToString("HH:mm:ss")+"\n\nBẢN VẼ ĐÍCH\n"+Path.GetFileName(d.Name)+"\n\nNHIỆM VỤ\n"+r.Plan.TaskId+" / "+r.Plan.SkillId+"\n\nPHẠM VI\n"+r.Plan.Scope.Count+" đỉnh · Model / mm\n\nTHAY ĐỔI\n"+r.Plan.Operations.Count+" thao tác tạo mới\nKhông sửa/xóa đối tượng hiện có\n\nTEMPLATE\n"+r.Plan.Template.Name+" / "+r.Plan.Template.Version+"\n\nPLAN\n"+r.Hash.Substring(0,16)+(showGraphics?"\n\nXem các nét màu xanh trong bản vẽ.":"\n\nĐã kiểm tra hình học; chế độ này không hiển thị nét xanh.")+"\nDuyệt/hủy không gọi AI lại.";d.Editor.UpdateScreen();}}
 void DemandResources(DrawingPlan plan){NativeLibraryAssets.Demand(plan);var store=new ContentStore(plugin.Config.ContentRoot);if(!store.Enabled(plan.SkillId)||JsonUtil.Hash(store.Template(plan.Template.Id,plan.Template.Version))!=plan.TemplateHash||JsonUtil.Hash(store.Skill(plan.SkillId,plan.SkillVersion))!=plan.SkillHash)throw new CadException("RESOURCE_CHANGED","Skill or Template changed. Create a new plan.");}
 void DemandSources(DrawingPlan plan){foreach(var source in plan.Sources){if(source.DocumentId!=""){if(source.SessionId!=plugin.Context.SessionId)throw new CadException("SOURCE_SESSION","Source DWG must be in this AutoCAD session.");plugin.Context.Resolve(source.DocumentId,source.Revision);}else if(source.SourceId!=""){string meta=Path.Combine(plugin.Config.DataRoot,"sources",JsonUtil.Id(source.SourceId)+".analysis.json");if(!File.Exists(meta)||JsonUtil.FileHash(meta)!=source.Hash)throw new CadException("SOURCE_CHANGED","Source analysis changed.");}}}
 void Demand(){if(current==null||document==null||DateTime.UtcNow>expires||AcApp.DocumentManager.MdiActiveDocument!=document)throw new CadException("STALE_PREVIEW","Preview expired or target drawing changed.");plugin.Context.Resolve(current.Plan.DocumentId,revision);if(!palette.Visible||!document.Database.TileMode)throw new CadException("PREVIEW_REQUIRED","Review must be visible in the target Model space.");using(plugin.Plans.Lock(current.Plan.PlanId)){var stored=plugin.Plans.Read(current.Plan.PlanId);if(stored.Status!="PREVIEW"||stored.Hash!=current.Hash||JsonUtil.Hash(stored.Plan)!=current.Hash)throw new CadException("PLAN_CHANGED","Plan state or hash changed.");}DemandResources(current.Plan);DemandSources(current.Plan);}
 internal void ValidateLive(){if(current==null||DateTime.UtcNow-lastValidation<TimeSpan.FromMilliseconds(500))return;lastValidation=DateTime.UtcNow;try{if(plugin.Plans.Read(current.Plan.PlanId).Status!="PREVIEW"){Invalidate("Kế hoạch đã hủy hoặc không còn chờ duyệt.");return;}if(document==null||AcApp.DocumentManager.MdiActiveDocument!=document||!plugin.Context.Open.ContainsKey(document)||plugin.Context.Revision(document)!=revision||DateTime.UtcNow>expires||!palette.Visible)Invalidate("Preview hết hiệu lực. Tạo lại kế hoạch khi đổi file, revision hoặc đóng palette.");}catch{Invalidate("Preview hết hiệu lực.");}}
 void Invalidate(string reason){if(current!=null)try{using(plugin.Plans.Lock(current.Plan.PlanId)){var r=plugin.Plans.Read(current.Plan.PlanId);if(r.Status=="PREVIEW"){r.Status="STALE";r.Message=reason;plugin.Plans.Write(r);}}}catch(IOException){}Cleanup();current=null;approved=false;approve.Enabled=false;cancel.Enabled=false;detail.Text=reason;}
 void Cleanup(){foreach(var e in transient){try{TransientManager.CurrentTransientManager.EraseTransient(e,viewports);}finally{}}transient.Clear();scene?.Dispose();scene=null;}
 internal void Cancel(){if(current!=null){using(plugin.Plans.Lock(current.Plan.PlanId)){var r=plugin.Plans.Read(current.Plan.PlanId);if(r.Status=="PREVIEW"){r.Status="CANCELLED";r.Message="User cancelled local preview. No CAD mutation.";plugin.Plans.Write(r);}}}Cleanup();current=null;approved=false;approve.Enabled=false;cancel.Enabled=false;detail.Text="Đã đóng bản xem trước. Không thay đổi DWG.";}
 internal void ApplyWithFeedback(){string id=current?.Plan.PlanId??"";try{Apply();}catch(System.Exception e){if(id!=""){var saved=plugin.Plans.Read(id);if(saved.Status=="PREVIEW"||saved.Status=="READY")Invalidate(e.Message);else if(saved.Status!="DONE"){Cleanup();current=null;approved=false;approve.Enabled=false;cancel.Enabled=false;detail.Text="KHÔNG HOÀN TẤT\n\n"+saved.Status+"\n"+saved.Message;}}throw;}}
 internal void Apply(){if(!approved)throw new CadException("APPROVAL_REQUIRED","Approve this exact preview in the AutoCAD palette first.");Demand();approved=false;var r=current!;var d=document!;string planId=r.Plan.PlanId;using var planLock=plugin.Plans.Lock(planId);r=plugin.Plans.Read(planId);using var writer=new Mutex(false,"Local\\AICadDrawing_"+JsonUtil.Hash(plugin.Context.DrawingKey(d)));bool locked=false;try{try{locked=writer.WaitOne(0);}catch(AbandonedMutexException){locked=true;}if(!locked)throw new CadException("BUSY","Another writer holds this physical DWG.");var barrier=new ExecutionBarrier(plugin.Config.DataRoot,plugin.Context.DrawingKey(d));barrier.DemandAvailable();using var docLock=d.LockDocument();NativeWriteGuard.Check(d);plugin.Context.Resolve(r.Plan.DocumentId,r.Plan.DocumentRevision);DemandResources(r.Plan);DemandSources(r.Plan);Cleanup();if(r.Status!="PREVIEW")throw new CadException("INVALID_STATE","Plan already dispatched.");string receiptKey="AICAD_"+r.Plan.PlanId;using(var check=d.Database.TransactionManager.StartOpenCloseTransaction()){var nod=(DBDictionary)check.GetObject(d.Database.NamedObjectsDictionaryId,OpenMode.ForRead);if(nod.Contains(receiptKey))throw new CadException("ALREADY_APPLIED","Transactional receipt already exists. Do not retry.");}
 Directory.CreateDirectory(Path.Combine(plugin.Config.DataRoot,"checkpoints"));r.CheckpointPath=Path.Combine(plugin.Config.DataRoot,"checkpoints",r.Plan.PlanId+".dwg");using(var backup=d.Database.Wblock())backup.SaveAs(r.CheckpointPath,DwgVersion.AC1032);r.Status="DISPATCHED";r.ExecutionId=Guid.NewGuid().ToString("N");r.Message="Native execution started; reconcile receipt if interrupted.";barrier.Dispatch(planId,r.ExecutionId);plugin.Plans.Write(r);plugin.Context.OwnedWrite=true;bool undoGroup=false;bool committed=false;try{d.Editor.Command("_.UNDO","_BEGIN");undoGroup=true;using(var tx=d.Database.TransactionManager.StartTransaction()){var nativeEntities=EntityFactory.WritePlan(r.Plan,d.Database,tx);r.EntityHandles=nativeEntities.Select(e=>e.Handle.ToString()).ToList();var nod=(DBDictionary)tx.GetObject(d.Database.NamedObjectsDictionaryId,OpenMode.ForWrite);var receipt=new Xrecord{Data=new ResultBuffer(new TypedValue((int)DxfCode.Text,r.Hash),new TypedValue((int)DxfCode.Text,r.ExecutionId),new TypedValue((int)DxfCode.Text,JsonUtil.Hash(r.EntityHandles)))};nod.SetAt(receiptKey,receipt);tx.AddNewlyCreatedDBObject(receipt,true);tx.Commit();committed=true;}plugin.Context.Open[d].Revision++;r.Status="DONE";r.QaStatus="PASSED";r.Message="Committed. Native bounds/layer checks passed; receipt stored in DWG. Save DWG to persist across closing.";plugin.Plans.Write(r);barrier.Finish(planId,r.ExecutionId,"DONE");detail.Text="HOÀN TẤT\n\n"+r.EntityHandles.Count+" đối tượng CAD đã tạo.\n\nQA phạm vi/layer: đạt.\nReceipt đã lưu trong transaction DWG.\n\nBạn có thể chỉnh sửa tiếp hoặc Undo một lần.\nLưu DWG để giữ kết quả.";}catch(System.Exception e){r.Status=committed?"UNKNOWN":"FAILED";r.Message=committed?"Commit may have succeeded. Inspect transactional receipt; do not retry.":"Transaction rolled back: "+e.Message;try{plugin.Plans.Write(r);if(!committed)barrier.Finish(planId,r.ExecutionId,"FAILED");}catch{}throw;}finally{try{if(undoGroup)d.Editor.Command("_.UNDO","_END");}finally{plugin.Context.OwnedWrite=false;current=null;approve.Enabled=false;cancel.Enabled=false;}}}finally{if(locked)writer.ReleaseMutex();}d.Editor.UpdateScreen();}
